package com.northstarbank.console.service;import com.northstarbank.console.domain.*;import com.northstarbank.console.security.AuthorizationService;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import org.springframework.stereotype.Service;
@Service public class AuditService{private final AuditRepository repo;private final AuthorizationService auth;public AuditService(AuditRepository r,AuthorizationService a){repo=r;auth=a;}public void record(String action,String type,int count,String customer,String basis,String before,String after){var u=auth.user();repo.save(new AuditEvent(u.employeeId(),action,type,count,opaque(customer),u.scope(),basis,before,after));}private String opaque(String s){if(s==null)return null;try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8))).substring(0,16);}catch(Exception e){throw new IllegalStateException(e);}}}
